export type GameQuestStep = {
  id: string;
  label: string;
  how?: string;
  location?: string;
  reward?: string;
  why?: string;
  /** Items consumed or required by this step. The UI expands every known acquisition route from GAME_ITEM_SOURCES. */
  requiredItems?: GameRequiredItem[];
  /** This milestone is confirmed complete in the user's current save and should not reappear as active work. */
  currentSaveComplete?: boolean;
  bucket: GameQuestBucket;
  priority?: number;
  importance?: GameImportance;
  /** Calendar-only gate. Story prerequisites belong in requires. */
  gate?: {
    year?: number;
    seasons?: string[];
    minDay?: number;
    maxDay?: number;
    minTotalDay?: number;
    weather?: ("sunny" | "rain" | "storm" | "snow")[];
  };
  /** Other quest-board steps that must be checked first, formatted as storylineId:stepId. */
  requires?: string[];
  /** Farm & Progression checkboxes that must be checked first. */
  requiresProgress?: { label: string; ref: ProgressionRef }[];
  /** Friendship target used by the daily social-priority dashboard. */
  social?: {
    npc: string;
    hearts: number;
    personal?: boolean;
    why?: string;
    startAfterStepId?: string;
    startAfterProgress?: ProgressionRef;
  };
  unlock?: string;
  /** Reuse an existing phase checkbox so old progress is preserved. */
  legacy?: { phaseId: string; groupLabel: string; text: string };
  /** Reuse a quest-step key when a step moves to a different storyline card. */
  progressKey?: { storylineId: string; stepId: string };
};

export type GameStoryline = {
  id: string;
  title: string;
  mod: string;
  note?: string;
  importance?: GameImportance;
  /** Keep the saved keys, but remove this earlier-stage card from the active guide after Community Center completion. */
  archiveAfterCommunityCenter?: boolean;
  steps: GameQuestStep[];
};

export type ProgressionItem = {
  label: string;
  how?: string;
  why?: string;
  /** Materials needed for this progression item, with alternate acquisition routes shown in the UI. */
  requiredItems?: GameRequiredItem[];
  /** Legacy/farm progression checkbox to reuse. Use exactly one of ref or questRef. */
  ref?: ProgressionRef;
  /** Story & Quests step to reuse so both tabs share one checkbox. */
  questRef?: { storylineId: string; stepId: string };
};

export type ProgressionSection = {
  id: string;
  title: string;
  note?: string;
  items: ProgressionItem[];
};

export type GameQuestBoard = {
  storylines: GameStoryline[];
};

/** A live quest/progression checklist. Legacy phase data is retained only to preserve saved checkbox keys. */
export type ChecklistGame = {
  kind: "checklist";
  id: string;
  tab: string;
  title: string;
  mods: string;
  saveLabel: string;
  saveDefault: string;
  rule: { text: string; notLabel: string; not: string[] };
  /** Live, non-linear quest board: the main play direction. */
  questBoard: GameQuestBoard;
  /** General how-tos shown on the page: how events trigger, and what to do with a finished day. */
  guide: { events: string[]; early: string[] };
  phases: GamePhase[];
};

export const SEASONS = ["Spring", "Summer", "Fall", "Winter"] as const;
export type Season = (typeof SEASONS)[number];

export type BundleItem = {
  name: string;
  /** Only needed when two slots in one bundle share a name, e.g. two stacks of Wood. */
  id?: string;
  qty?: number;
  quality?: string;
  /** Seasons this item can be gotten in, or "any" for year-round. */
  seasons: Season[] | "any";
  note?: string;
};

export type Bundle = {
  id: string;
  room: string;
  name: string;
  /** How many of the items must be given. Equal to items.length when every item is required. */
  need: number;
  items: BundleItem[];
};

/** A bundle tracker: items are grouped by the season they can be gotten in. */
export type GoldenWalnutItem = {
  id: string;
  label: string;
  how: string;
  /** Number of walnuts granted by this one completed source. Defaults to 1. */
  qty?: number;
  /** Leo's parrot never gives a hint for this source. */
  unhinted?: boolean;
};

export type GoldenWalnutGroup = {
  id: string;
  title: string;
  total: number;
  items: GoldenWalnutItem[];
};

export type BundleGame = {
  kind: "bundles";
  id: string;
  tab: string;
  title: string;
  mods: string;
  defaultSeason: Season;
  rooms: string[];
  bundles: Bundle[];
  footnotes: string[];
  progression?: ProgressionSection[];
  /** Exact 130-walnut source tracker for Ginger Island. */
  goldenWalnuts?: GoldenWalnutGroup[];
  /** Personal-save stage override when the Community Center is complete in game even if tracker boxes are stale. */
  postCompletionActive?: boolean;
  /** Replaces the bundle-gathering dashboard once the Community Center stage is complete. */
  postCompletion?: ProgressionSection[];
};

export type CompletionCategory = {
  id: string;
  title: string;
  items: string[];
  note?: string;
  sourceHint?: string;
  allowCustom?: boolean;
};

export type CompletionSection = {
  id: string;
  title: string;
  note?: string;
  categories: CompletionCategory[];
};

export type CompletionGame = {
  kind: "completion";
  id: string;
  tab: string;
  title: string;
  mods: string;
  sections: CompletionSection[];
};

export type Game = ChecklistGame | BundleGame | CompletionGame;

export type GameProgress = {
  checks: Record<string, true>;
  fields: Record<string, string>;
};

/** A change to saved progress. checks: true sets a box, false clears it. reset wipes the game first. */
export type GameProgressPatch = {
  reset?: boolean;
  checks?: Record<string, boolean>;
  fields?: Record<string, string>;
};

export const emptyProgress = (): GameProgress => ({ checks: {}, fields: {} });

export const itemKey = (gameId: string, phaseId: string, groupLabel: string, text: string) =>
  [gameId, phaseId, groupLabel, text].join("|");
export const questKey = (gameId: string, storylineId: string, stepId: string) =>
  [gameId, "quest", storylineId, stepId].join("|");
export const fieldKey = (gameId: string, phaseId: string, name: string) => `${gameId}|${phaseId}|field|${name}`;
export const saveKey = (gameId: string) => `${gameId}|save`;
export const weatherKey = (gameId: string) => `${gameId}|weather`;
export const mainQuestKey = (gameId: string) => `${gameId}|main-quest`;

export const seasonKey = (gameId: string) => `${gameId}|season`;
export const bundleItemKey = (gameId: string, bundleId: string, item: BundleItem) =>
  [gameId, bundleId, item.id ?? item.name].join("|");
export const goldenWalnutKey = (gameId: string, groupId: string, itemId: string) =>
  [gameId, "golden-walnut", groupId, itemId].join("|");
export const completionItemKey = (gameId: string, categoryId: string, item: string) =>
  [gameId, "completion", categoryId, item].join("|");
export const completionCustomItemsKey = (gameId: string, categoryId: string) => `${gameId}|completion|${categoryId}|custom-items`;
// Legacy quantity fields are retained only so an older deployed page cannot corrupt a save while this update rolls out.
export const completionCountKey = (gameId: string, categoryId: string) => `${gameId}|completion|${categoryId}|count`;
export const completionTotalKey = (gameId: string, categoryId: string) => `${gameId}|completion|${categoryId}|total`;
export const completionTargetsKey = (gameId: string, categoryId: string) => `${gameId}|completion|${categoryId}|targets`;

export const isBundleGame = (game: Game): game is BundleGame => game.kind === "bundles";
export const isCompletionGame = (game: Game): game is CompletionGame => game.kind === "completion";

/** Every box key a game can have, used to reject anything else on save. */
export function knownCheckKeys(game: Game): Set<string> {
  const keys = new Set<string>();
  if (isCompletionGame(game)) {
    game.sections.forEach((section) =>
      section.categories.forEach((category) =>
        category.items.forEach((item) => keys.add(completionItemKey(game.id, category.id, item))),
      ),
    );
    return keys;
  }
  if (isBundleGame(game)) {
    game.bundles.forEach((b) => b.items.forEach((i) => keys.add(bundleItemKey(game.id, b.id, i))));
    game.goldenWalnuts?.forEach((group) =>
      group.items.forEach((item) => keys.add(goldenWalnutKey(game.id, group.id, item.id))),
    );
    return keys;
  }
  game.questBoard.storylines.forEach((story) =>
    story.steps.forEach((step) => {
      if (!step.legacy) {
        const owner = step.progressKey ?? { storylineId: story.id, stepId: step.id };
        keys.add(questKey(game.id, owner.storylineId, owner.stepId));
      }

      // The UI saves incremental subtasks under the storyline's own key (not progressKey).
      // They must be accepted here or the progress API silently discards the checkmarks.
      for (const subtask of getStardewQuestSubtasks(story, step)) {
        keys.add(questKey(game.id, story.id, `${step.id}:subtask:${subtask.id}`));
      }
    }),
  );
  game.phases.forEach((p) =>
    p.groups.forEach((g) => g.items.forEach((t) => keys.add(itemKey(game.id, p.id, g.label, t)))),
  );
  return keys;
}

/** Every text-field key a game can have. */
export function knownFieldKeys(game: Game): Set<string> {
  if (isCompletionGame(game)) {
    const keys = new Set<string>();
    game.sections.forEach((section) =>
      section.categories.forEach((category) => {
        keys.add(completionCustomItemsKey(game.id, category.id));
        keys.add(completionCountKey(game.id, category.id));
        keys.add(completionTotalKey(game.id, category.id));
        keys.add(completionTargetsKey(game.id, category.id));
      }),
    );
    return keys;
  }
  if (isBundleGame(game)) return new Set<string>([seasonKey(game.id)]);
  const keys = new Set<string>([saveKey(game.id), weatherKey(game.id), mainQuestKey(game.id)]);
  game.phases.forEach((p) => p.groups.forEach((g) => g.field && keys.add(fieldKey(game.id, p.id, g.field))));
  return keys;
}

